```c
#include <immintrin.h> // For SSE intrinsics

// Assume vec_a, vec_b, vec_c are float arrays, 16-byte aligned
// float vec_a[4] = {1.0f, 2.0f, 3.0f, 4.0f};
// float vec_b[4] = {5.0f, 6.0f, 7.0f, 8.0f};
// float vec_c[4];

__m128 a = _mm_load_ps(vec_a);    // Load 4 floats into __m128 register
__m128 b = _mm_load_ps(vec_b);
__m128 result = _mm_add_ps(a, b); // Perform parallel addition
_mm_store_ps(vec_c, result);      // Store result back to memory
```
`_mm_load_ps` loads packed single-precision floats, `_mm_add_ps` performs packed addition, and `_mm_store_ps` stores packed single-precision floats.
